import{_ as a,o as i,c as t,a2 as l}from"./chunks/framework.BbQrW5_t.js";const E=JSON.parse('{"title":"蓝队监测与 ATT&CK","description":"","frontmatter":{"title":"蓝队监测与 ATT&CK","date":"2026-09-03T00:00:00.000Z","tags":["网络安全","中级"]},"headers":[],"relativePath":"study/cyber-security/chapters/中级篇/08-蓝队监测与ATTACK.md","filePath":"study/cyber-security/chapters/中级篇/08-蓝队监测与ATTACK.md","lastUpdated":1788493831000}'),e={name:"study/cyber-security/chapters/中级篇/08-蓝队监测与ATTACK.md"};function n(h,s,p,d,r,k){return i(),t("div",null,[...s[0]||(s[0]=[l(`<h1 id="_08-·-蓝队监测与-att-ck——告警背后的人" tabindex="-1">08 · 蓝队监测与 ATT&amp;CK——告警背后的人 <a class="header-anchor" href="#_08-·-蓝队监测与-att-ck——告警背后的人" aria-label="Permalink to &quot;08 · 蓝队监测与 ATT&amp;CK——告警背后的人&quot;">​</a></h1><blockquote><p>SIEM 每天推给你 3000 条告警；初级岗的价值=把真威胁从噪音里捞出来。这一章教你<strong>研判方法论</strong>与<strong>检测工程入门</strong>——护网蓝队岗的核心技能树。</p></blockquote><h2 id="🎯-学习目标" tabindex="-1">🎯 学习目标 <a class="header-anchor" href="#🎯-学习目标" aria-label="Permalink to &quot;🎯 学习目标&quot;">​</a></h2><ol><li>画出 SIEM 数据流水线</li><li>在 Wazuh 写出第一条自定义规则</li><li>用&quot;三问法&quot;完成一次告警研判</li><li>把已学攻击技术映射到 ATT&amp;CK 矩阵</li></ol><h2 id="📖-核心知识" tabindex="-1">📖 核心知识 <a class="header-anchor" href="#📖-核心知识" aria-label="Permalink to &quot;📖 核心知识&quot;">​</a></h2><h3 id="_8-1-siem-流水线" tabindex="-1">8.1 SIEM 流水线 <a class="header-anchor" href="#_8-1-siem-流水线" aria-label="Permalink to &quot;8.1 SIEM 流水线&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>日志源 ──采集──&gt; 归一化(字段标准化) ──&gt; 规则/UEBA ──&gt; 告警 ──&gt; [人] 研判 ──&gt; 处置</span></span>
<span class="line"><span>(Web/OS/EDR/网络设备)      Agent/Syslog          关联/聚合/基线            工单/封禁/应急</span></span></code></pre></div><p>蓝队的本质：<strong>日志质量决定检测上限</strong>。垃圾进垃圾出——所以&quot;平常有没有开审计&quot;是蓝队最先盘点的事。</p><h3 id="_8-2-wazuh-自定义规则入门" tabindex="-1">8.2 Wazuh 自定义规则入门 <a class="header-anchor" href="#_8-2-wazuh-自定义规则入门" aria-label="Permalink to &quot;8.2 Wazuh 自定义规则入门&quot;">​</a></h3><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- /var/ossec/etc/rules/local_rules.xml --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">group</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;local,webshell,&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">rule</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;100100&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> level</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;10&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">if_sid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;31108&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">if_sid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;              </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- Web 请求类父规则 --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">regex</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;POST /upload/.+\\.php&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">regex</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- 上传目录被 POST 执行 --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;疑似 webshell 执行：上传目录 POST 请求&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">rule</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">group</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>要素：id（100000+ 自定义段）/ level（告警级别）/ if_sid（继承父规则）/ regex|match（特征）。写规则的思维：<strong>把&quot;攻击的日志特征&quot;翻译成&quot;字段的正则+阈值+关联&quot;</strong>。</p><h3 id="_8-3-告警研判三问法" tabindex="-1">8.3 告警研判三问法 <a class="header-anchor" href="#_8-3-告警研判三问法" aria-label="Permalink to &quot;8.3 告警研判三问法&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一问真实性：日志可信吗？（IP 可伪造吗？时间线连续吗？代理日志 vs 主机日志对得上吗？）</span></span>
<span class="line"><span>二问严重性：影响什么资产/数据？漏洞可利用性？横向可能？</span></span>
<span class="line"><span>三问下一步：立即处置（封IP/隔离）还是升级（应急）？要哪些补充信息？</span></span></code></pre></div><p><strong>误报治理</strong>：每类告警建&quot;误报白名单&quot;（如扫描器自身 IP、变更窗口）——但白名单要写明&quot;为什么+有效期&quot;，防止成为黑洞。</p><h3 id="_8-4-流量侧检测概念" tabindex="-1">8.4 流量侧检测概念 <a class="header-anchor" href="#_8-4-流量侧检测概念" aria-label="Permalink to &quot;8.4 流量侧检测概念&quot;">​</a></h3><table tabindex="0"><thead><tr><th>特征</th><th>检测点</th></tr></thead><tbody><tr><td>Webshell 流量</td><td>POST 到上传目录、请求响应长度分布异常、UA 与行为不匹配</td></tr><tr><td>C2 心跳</td><td>固定间隔外连（间隔方差小）、低流量长连接、DGA 域名（随机字母长域名）</td></tr><tr><td>DNS 隧道</td><td>单域名 TXT 查询量异常、子域名熵值高</td></tr><tr><td>横向扫描</td><td>内网 ICMP/TCP 扫描模式、SMB 认证风暴</td></tr></tbody></table><h3 id="_8-5-att-ck-矩阵-攻防的公共语言" tabindex="-1">8.5 ATT&amp;CK 矩阵：攻防的公共语言 <a class="header-anchor" href="#_8-5-att-ck-矩阵-攻防的公共语言" aria-label="Permalink to &quot;8.5 ATT&amp;CK 矩阵：攻防的公共语言&quot;">​</a></h3><p>结构：14 个战术（列：初始访问→影响）× 每战术下技术（行：如 T1059 命令脚本解释器）。</p><p><strong>映射练习</strong>（用已学中级内容填）：</p><table tabindex="0"><thead><tr><th>已学技术</th><th>ATT&amp;CK 战术</th><th>技术编号（示例）</th></tr></thead><tbody><tr><td>钓鱼/边界利用</td><td>初始访问</td><td>T1566/T1190</td></tr><tr><td>webshell</td><td>持久化</td><td>T1505.003</td></tr><tr><td>PsExec 横向</td><td>横向移动</td><td>T1021.002</td></tr><tr><td>Kerberoasting</td><td>凭据访问</td><td>T1558.003</td></tr><tr><td>计划任务后门</td><td>持久化</td><td>T1053</td></tr></tbody></table><p>价值：有了编号，检测规则、报告、复盘全部对齐同一种语言——这是与国际接轨的&quot;术语操作系统&quot;。</p><h3 id="_8-6-sigma-入门" tabindex="-1">8.6 Sigma 入门 <a class="header-anchor" href="#_8-6-sigma-入门" aria-label="Permalink to &quot;8.6 Sigma 入门&quot;">​</a></h3><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">上传目录 Webshell 执行</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">logsource</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    category</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">webserver</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">detection</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    sel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        cs-method</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;POST&#39;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        cs-uri-stem|contains</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;/upload/&#39;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        c-extension</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;.php&#39;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    condition</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">sel</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">level</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">high</span></span></code></pre></div><p>Sigma = 检测规则的&quot;跨平台普通话&quot;（一份 YAML 转 Splunk/Elastic/Wazuh 规则）——检测工程的可移植资产。</p><h2 id="🔬-动手实操" tabindex="-1">🔬 动手实操 <a class="header-anchor" href="#🔬-动手实操" aria-label="Permalink to &quot;🔬 动手实操&quot;">​</a></h2><p>Wazuh 单机部署（docker 或 OVA）→ 造 3 个事件（暴破失败/webshell 请求/新用户创建）→ 观察默认告警 → 为其中之一写自定义规则 → 触发验证。</p><h2 id="⚠️-常见坑" tabindex="-1">⚠️ 常见坑 <a class="header-anchor" href="#⚠️-常见坑" aria-label="Permalink to &quot;⚠️ 常见坑&quot;">​</a></h2><ol><li>只学工具不学研判——工具会变，方法论不变</li><li>规则一写就&quot;level 15 全网告警&quot;——告警疲劳是检测工程第一杀手</li><li>把 ATT&amp;CK 当背书材料——它是映射工具，用起来才有价值</li><li>忽略白名单管理——半年后没人知道某条白名单为什么存在</li><li>只看告警不看基线——&quot;正常长什么样&quot;都不知道，异常无从谈起</li></ol><h2 id="✅-自测题" tabindex="-1">✅ 自测题 <a class="header-anchor" href="#✅-自测题" aria-label="Permalink to &quot;✅ 自测题&quot;">​</a></h2><details><summary>1. 为什么说&quot;日志质量决定检测上限&quot;？</summary><p>规则再好，日志缺字段（如未开命令审计/未记录 DNS）就永远检不出对应行为——数据源覆盖先于规则编写。</p></details><details><summary>2. 研判&quot;外连 C2 心跳&quot;最关键的证据？</summary><p>外连时序规律性（固定间隔/抖动极小）+ 目标域名/IP 情报 + 结合主机侧是否有对应进程——单靠流量特征容易误判定时任务。</p></details><details><summary>3. ATT&amp;CK 映射对护网蓝队的实际用处？</summary><p>统一攻击描述语言：值班报告写&quot;T1059+T1053 组合&quot;各方即时理解；也用于盘点检测覆盖（哪些战术有日志无规则）。</p></details><details><summary>4. 告警级别怎么定才不疲劳？</summary><p>按&quot;置信度×影响&quot;分级：高置信高影响才 high；低置信但可观测的放 low/info 只记录不推送——推送量控制在人能处理的上限内。</p></details><details><summary>5. Sigma 的核心价值？</summary><p>检测逻辑与平台解耦：一次编写，可转换到 Splunk/Elastic/QRadar 等——规则成为可迁移的组织资产。</p></details><h2 id="🔗-对应周任务与资源" tabindex="-1">🔗 对应周任务与资源 <a class="header-anchor" href="#🔗-对应周任务与资源" aria-label="Permalink to &quot;🔗 对应周任务与资源&quot;">​</a></h2><ul><li><strong>W81-W84</strong>；资源：ATT&amp;CK 官网、Sigma HQ 规则库、Wazuh 文档 Ruleset 章节</li></ul>`,36)])])}const g=a(e,[["render",n]]);export{E as __pageData,g as default};
